package com.fincore.fincore.account; import java.math.BigDecimal; import java.time.Instant; import com.fincore.fincore.user.User; import jakarta.persistence.*; @Entity @Table(name="accounts") public class Account { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,length=100) private String name; @Enumerated(EnumType.STRING) @Column(name="account_type",nullable=false,length=30) private AccountType accountType; @Column(nullable=false,precision=19,scale=2) private BigDecimal balance; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id") private User user; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt; protected Account(){} public Account(String n,AccountType t,BigDecimal b,User u){name=n;accountType=t;balance=b;user=u;} @PrePersist void c(){var n=Instant.now();createdAt=n;updatedAt=n;} @PreUpdate void u(){updatedAt=Instant.now();} public Long getId(){return id;} public String getName(){return name;} public AccountType getAccountType(){return accountType;} public BigDecimal getBalance(){return balance;} public User getUser(){return user;} public Instant getCreatedAt(){return createdAt;} public void setName(String v){name=v;} public void setBalance(BigDecimal v){balance=v;} }
